dashboard.definition:
{
  "visualizations": {
    "viz_state": {
      "type": "splunk.singlevalue",
      "options": {
        "majorValue": "> primary | seriesByName('state') | lastPoint()",
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      },
      "dataSources": {
        "primary": "ds_state"
      },
      "title": "Current state"
    },
    "viz_workers": {
      "type": "splunk.singlevalue",
      "options": {
        "majorValue": "> primary | seriesByName('workers') | lastPoint()",
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      },
      "dataSources": {
        "primary": "ds_workers"
      },
      "title": "Reporting / live workers"
    },
    "viz_eps": {
      "type": "splunk.singlevalue",
      "options": {
        "majorValue": "> primary | seriesByName('eps') | lastPoint()",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "unit": "eps",
        "unitPosition": "after"
      },
      "dataSources": {
        "primary": "ds_eps"
      },
      "title": "Delivered eps"
    },
    "viz_events": {
      "type": "splunk.singlevalue",
      "options": {
        "majorValue": "> primary | seriesByName('events') | lastPoint()",
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      },
      "dataSources": {
        "primary": "ds_events"
      },
      "title": "Events delivered"
    },
    "viz_bytes": {
      "type": "splunk.singlevalue",
      "options": {
        "majorValue": "> primary | seriesByName('mb') | lastPoint()",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "unit": "MB",
        "unitPosition": "after"
      },
      "dataSources": {
        "primary": "ds_bytes"
      },
      "title": "MB delivered"
    },
    "viz_eps_ts": {
      "type": "splunk.line",
      "options": {
        "legendDisplay": "bottom",
        "yAxisTitleText": "events / s",
        "nullValueDisplay": "connect"
      },
      "dataSources": {
        "primary": "ds_eps_ts"
      },
      "title": "Delivered eps vs target"
    },
    "viz_mbps_ts": {
      "type": "splunk.line",
      "options": {
        "legendDisplay": "bottom",
        "yAxisTitleText": "MB / s",
        "nullValueDisplay": "connect"
      },
      "dataSources": {
        "primary": "ds_mbps_ts"
      },
      "title": "Delivered MB/s"
    },
    "viz_lag_ts": {
      "type": "splunk.line",
      "options": {
        "legendDisplay": "bottom",
        "yAxisTitleText": "seconds behind",
        "nullValueDisplay": "connect"
      },
      "dataSources": {
        "primary": "ds_lag_ts"
      },
      "title": "Pacing lag (max across workers)"
    },
    "viz_hec_ts": {
      "type": "splunk.line",
      "options": {
        "legendDisplay": "bottom",
        "yAxisTitleText": "count",
        "nullValueDisplay": "connect"
      },
      "dataSources": {
        "primary": "ds_hec_ts"
      },
      "title": "HEC outcomes (cumulative)"
    },
    "viz_life": {
      "type": "splunk.table",
      "options": {
        "count": 20
      },
      "dataSources": {
        "primary": "ds_life"
      },
      "title": "Lifecycle (state transitions)"
    },
    "viz_slots": {
      "type": "splunk.table",
      "options": {
        "count": 20
      },
      "dataSources": {
        "primary": "ds_slots"
      },
      "title": "Workers: each slot against its share (latest)"
    },
    "viz_slot_eps": {
      "type": "splunk.line",
      "options": {
        "legendDisplay": "bottom",
        "yAxisTitleText": "events / s",
        "nullValueDisplay": "connect"
      },
      "dataSources": {
        "primary": "ds_slot_eps"
      },
      "title": "Delivered eps by slot"
    },
    "viz_slot_cpu": {
      "type": "splunk.line",
      "options": {
        "legendDisplay": "bottom",
        "yAxisTitleText": "% of CPU limit",
        "nullValueDisplay": "connect"
      },
      "dataSources": {
        "primary": "ds_slot_cpu"
      },
      "title": "Engine CPU by slot (% of the container's limit)"
    }
  },
  "dataSources": {
    "ds_state": {
      "type": "ds.search",
      "options": {
        "query": "index=$index_tok$ sourcetype=stoker:metrics run_id=$run_id_tok$\n| stats latest(state) as state",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "name": "State"
    },
    "ds_workers": {
      "type": "ds.search",
      "options": {
        "query": "index=$index_tok$ sourcetype=stoker:metrics run_id=$run_id_tok$\n| stats latest(reporting_workers) as reporting latest(live_workers) as live latest(unheld_slots) as unheld\n| eval workers = reporting . \" / \" . live . if(unheld>0, \" (\" . unheld . \" unheld)\", \"\")",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "name": "Workers"
    },
    "ds_eps": {
      "type": "ds.search",
      "options": {
        "query": "index=$index_tok$ sourcetype=stoker:metrics run_id=$run_id_tok$\n| stats latest(eps) as eps",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "name": "Delivered eps"
    },
    "ds_events": {
      "type": "ds.search",
      "options": {
        "query": "index=$index_tok$ sourcetype=stoker:metrics run_id=$run_id_tok$\n| stats max(events_total) as events",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "name": "Events"
    },
    "ds_bytes": {
      "type": "ds.search",
      "options": {
        "query": "index=$index_tok$ sourcetype=stoker:metrics run_id=$run_id_tok$\n| stats max(bytes_total) as bytes\n| eval mb = round(bytes/1024/1024, 1)",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "name": "Bytes"
    },
    "ds_eps_ts": {
      "type": "ds.search",
      "options": {
        "query": "index=$index_tok$ sourcetype=stoker:metrics run_id=$run_id_tok$\n| timechart span=30s avg(eps) as \"Delivered eps\" avg(target_eps) as \"Target eps\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "name": "Delivered vs target"
    },
    "ds_mbps_ts": {
      "type": "ds.search",
      "options": {
        "query": "index=$index_tok$ sourcetype=stoker:metrics run_id=$run_id_tok$\n| eval mbps = bps / 1048576\n| timechart span=30s avg(mbps) as \"Delivered MB/s\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "name": "Delivered MB/s"
    },
    "ds_lag_ts": {
      "type": "ds.search",
      "options": {
        "query": "index=$index_tok$ sourcetype=stoker:metrics run_id=$run_id_tok$\n| timechart span=30s max(lag_s_max) as \"Max pacing lag (s)\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "name": "Pacing lag"
    },
    "ds_hec_ts": {
      "type": "ds.search",
      "options": {
        "query": "index=$index_tok$ sourcetype=stoker:metrics run_id=$run_id_tok$\n| timechart span=30s max(hec_2xx) as \"2xx\" max(hec_4xx) as \"4xx\" max(hec_5xx) as \"5xx\" max(hec_timeouts) as \"timeouts\" max(retries) as \"retries\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "name": "HEC outcomes"
    },
    "ds_life": {
      "type": "ds.search",
      "options": {
        "query": "index=$index_tok$ sourcetype=stoker:job run_id=$run_id_tok$\n| sort - _time\n| table _time from to end_reason degraded",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "name": "Lifecycle"
    },
    "ds_slots": {
      "type": "ds.search",
      "options": {
        "query": "index=$index_tok$ sourcetype=stoker:worker run_id=$run_id_tok$\n| stats latest(lease_state) as state latest(holder) as holder latest(engine_impl) as engine latest(share_eps) as share_eps latest(eps) as eps latest(eps_of_share_pct) as of_share latest(engine_cpu_pct) as engine_cpu latest(cpu_limit_cores) as cores latest(engine_cpu_of_limit_pct) as of_limit latest(engine_threads) as threads latest(lag_s) as lag_s latest(queue_depth) as queue latest(rss_mb) as rss_mb latest(heartbeat_age_s) as hb_age by slot\n| eval verdict=case(state=\"free\", \"unheld: no worker claimed this slot\", state=\"lost\", \"lost: worker stopped heartbeating\", hb_age>60, \"silent for \".round(hb_age).\" s\", of_limit>=90, \"engine CPU-bound\", queue>0, \"HEC queue backing up\", lag_s>5, \"behind schedule\", isnotnull(of_share) AND of_share<90, \"under share\", true(), \"ok\")\n| eval eps=round(eps, 0), share_eps=round(share_eps, 0), lag_s=round(lag_s, 1), rss_mb=round(rss_mb, 0)\n| sort slot\n| table slot state verdict holder engine share_eps eps of_share engine_cpu cores of_limit threads lag_s queue rss_mb",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "name": "Workers"
    },
    "ds_slot_eps": {
      "type": "ds.search",
      "options": {
        "query": "index=$index_tok$ sourcetype=stoker:worker run_id=$run_id_tok$ lease_state=running\n| eval slot=\"slot \".slot\n| timechart span=30s avg(eps) by slot limit=50",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "name": "Delivered eps by slot"
    },
    "ds_slot_cpu": {
      "type": "ds.search",
      "options": {
        "query": "index=$index_tok$ sourcetype=stoker:worker run_id=$run_id_tok$ lease_state=running\n| eval slot=\"slot \".slot\n| timechart span=30s max(engine_cpu_of_limit_pct) by slot limit=50",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "name": "Engine CPU by slot"
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "inputs": {
    "input_runid": {
      "type": "input.text",
      "title": "Run id",
      "options": {
        "token": "run_id_tok",
        "defaultValue": ""
      }
    },
    "input_time": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-60m,now"
      }
    },
    "input_index": {
      "type": "input.text",
      "title": "Index (dogfood target)",
      "options": {
        "token": "index_tok",
        "defaultValue": "*"
      }
    }
  },
  "layout": {
    "type": "absolute",
    "options": {
      "width": 1200,
      "height": 1800,
      "display": "auto"
    },
    "structure": [
      {
        "item": "viz_state",
        "type": "block",
        "position": {
          "x": 0,
          "y": 0,
          "w": 240,
          "h": 150
        }
      },
      {
        "item": "viz_workers",
        "type": "block",
        "position": {
          "x": 240,
          "y": 0,
          "w": 240,
          "h": 150
        }
      },
      {
        "item": "viz_eps",
        "type": "block",
        "position": {
          "x": 480,
          "y": 0,
          "w": 240,
          "h": 150
        }
      },
      {
        "item": "viz_events",
        "type": "block",
        "position": {
          "x": 720,
          "y": 0,
          "w": 240,
          "h": 150
        }
      },
      {
        "item": "viz_bytes",
        "type": "block",
        "position": {
          "x": 960,
          "y": 0,
          "w": 240,
          "h": 150
        }
      },
      {
        "item": "viz_eps_ts",
        "type": "block",
        "position": {
          "x": 0,
          "y": 160,
          "w": 600,
          "h": 300
        }
      },
      {
        "item": "viz_mbps_ts",
        "type": "block",
        "position": {
          "x": 610,
          "y": 160,
          "w": 590,
          "h": 300
        }
      },
      {
        "item": "viz_lag_ts",
        "type": "block",
        "position": {
          "x": 0,
          "y": 470,
          "w": 600,
          "h": 300
        }
      },
      {
        "item": "viz_hec_ts",
        "type": "block",
        "position": {
          "x": 610,
          "y": 470,
          "w": 590,
          "h": 300
        }
      },
      {
        "item": "viz_life",
        "type": "block",
        "position": {
          "x": 0,
          "y": 780,
          "w": 1200,
          "h": 280
        }
      },
      {
        "item": "viz_slots",
        "type": "block",
        "position": {
          "x": 0,
          "y": 1070,
          "w": 1200,
          "h": 400
        }
      },
      {
        "item": "viz_slot_eps",
        "type": "block",
        "position": {
          "x": 0,
          "y": 1480,
          "w": 600,
          "h": 300
        }
      },
      {
        "item": "viz_slot_cpu",
        "type": "block",
        "position": {
          "x": 610,
          "y": 1480,
          "w": 590,
          "h": 300
        }
      }
    ],
    "globalInputs": [
      "input_runid",
      "input_time",
      "input_index"
    ]
  },
  "title": "Stoker \u2014 Run Detail",
  "description": "One run by id, over dogfood telemetry: delivered vs target eps, pacing lag, HEC outcomes and lifecycle, then each slot against its share with its engine's CPU against the container's limit."
}
